do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'spanish-2';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Travel, Transportation and Directions$j$, $j${"readings": [{"title": "Psalm 121 (King James Version)", "url": "/portal/bible/Psalms/121"}], "body": "Psalm 121:8 says, The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore. Travel vocabulary helps you serve visitors and prepare for missions, trips and work.\n\nKey nouns are el aeropuerto (airport), la estación (station), el autobús (bus), el tren (train), el avión (airplane), el boleto (ticket), el pasaporte (passport), la maleta (suitcase), el vuelo (flight), el hotel (hotel), la reservación (reservation), la salida (departure or exit) and la llegada (arrival).\n\nUseful questions are ¿Dónde está la estación? ¿Cómo llego al aeropuerto? ¿A qué hora sale el vuelo? ¿Cuánto cuesta el boleto? A polite request uses quisiera: Quisiera comprar un boleto, por favor. Quisiera reservar una habitación.\n\nDirections use commands. Siga derecho means keep going straight. Doble a la derecha means turn right. Doble a la izquierda means turn left. Cruce la calle means cross the street. Está al lado de, enfrente de, cerca de and lejos de tell where a place is. Está a dos cuadras means it is two blocks away.\n\nWorked example: Perdón, ¿cómo llego al hotel? Siga derecho dos cuadras y doble a la izquierda. Está enfrente de la iglesia. Common mistake: using tú commands with a stranger. Use usted: siga, doble, cruce.\n\nYour task: (1) Write a dialogue of eight lines in which a visitor asks directions to your church. (2) List ten travel words with their meanings.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Psalm 121:8 says, The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore. Let us learn the language of travel.\n\nNow watch this. Key words: el aeropuerto, la estación, el autobús, el tren, el boleto, el pasaporte, la maleta, el vuelo, el hotel, la reservación.\n\nQuestions: ¿Dónde está la estación? ¿Cómo llego al aeropuerto? ¿A qué hora sale el vuelo? Be polite with quisiera. Quisiera comprar un boleto.\n\nDirections use usted commands. Siga derecho. Doble a la derecha. Doble a la izquierda. Cruce la calle.\n\nPlaces: al lado de, enfrente de, cerca de, lejos de. Está a dos cuadras.\n\nYour task is to write a dialogue about directions to your church and list ten travel words. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Travel, Transportation and Directions$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Health, the Pharmacy and Emergencies$j$, $j${"readings": [{"title": "James 5 (King James Version)", "url": "/portal/bible/James/5"}], "body": "James 5:14 says, Is any sick among you? let him call for the elders of the church; and let them pray over him, anointing him with oil in the name of the Lord. The church has always cared for the sick, and Spanish helps you comfort and assist neighbors.\n\nReview the body and add symptoms. Tengo fiebre means I have a fever. Tengo tos means I have a cough. Tengo dolor de cabeza, de garganta, de estómago. Estoy mareado means I am dizzy. Soy alérgico a means I am allergic to. Places and people include la farmacia, la clínica, el hospital, el médico, la enfermera, la receta and la medicina.\n\nUseful phrases are ¿Dónde le duele? ¿Cuánto tiempo hace que está enfermo? Tome una pastilla cada ocho horas. Descanse y beba mucha agua. Formal commands are used because you are speaking with an adult.\n\nIn an emergency, say Es una emergencia. Llame al 911. Necesito ayuda. Hay un accidente. Estoy aquí con usted.\n\nWorked example: Doctor, tengo dolor de garganta y fiebre desde ayer. Common mistake: giving medical advice. A volunteer comforts, listens and calls for help, but does not diagnose or prescribe. For anything serious, call a doctor or 911 and ask for a trained medical interpreter.\n\nYour task: (1) Write a dialogue of eight lines between a patient and a pharmacist. (2) Write five emergency phrases and what each means.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, James 5:14 says, Is any sick among you? let him call for the elders of the church. The church cares for the sick, and Spanish helps us do that.\n\nNow watch this. Symptoms: tengo fiebre, tengo tos, tengo dolor de cabeza, de garganta, de estómago. Estoy mareado. Soy alérgico a.\n\nPlaces: la farmacia, la clínica, el hospital. People: el médico, la enfermera. Things: la receta, la medicina.\n\nPhrases: ¿Dónde le duele? Tome una pastilla cada ocho horas. Descanse y beba mucha agua.\n\nIn an emergency: Es una emergencia. Llame al 911. Necesito ayuda.\n\nRemember, a volunteer does not diagnose or prescribe. Call a professional and ask for a trained medical interpreter.\n\nYour task is to write a patient and pharmacist dialogue and five emergency phrases. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Health, the Pharmacy and Emergencies$j$);
end
$seed$;
